export const COSSENNE_ACTIVITY_ROOMS=['cossenneConservatory','cossenneApothecary','cossenneFirewatch'];
// Persistent activities in Cossenne. Every mutation is committed by the caller's save transaction.
export const CONSERVATORY_TYPES=['BUG','GRASS','WATER','FIRE','GROUND','ROCK'];
export const RELIEF_POSTS=[{key:'firebreak',room:'orchardFirebreak',id:'cs-relief-firebreak',name:'Firebreak dressings post',route:'Orchard Way · The Firebreak',x:14,y:13},{key:'slope',room:'orchardAshSlope',id:'cs-relief-slope',name:'Ashfall Slope water post',route:'Orchard Way · Ashfall Slope',x:10,y:22},{key:'renewal',room:'orchardRenewal',id:'cs-relief-renewal',name:'Green Return seed post',route:'Orchard Way · The Green Return',x:28,y:22}];
export const APOTHECARY_RECIPES=[{id:'dressing',name:'Field Dressing',key:'fieldDressings',poultices:2,price:250,text:'Restore up to 200 HP.'},{id:'draught',name:'Restorative Draught',key:'restorativeDraughts',poultices:4,price:900,text:'Restore 75% of maximum HP.'},{id:'balm',name:'Cleansing Balm',key:'cleansingBalms',poultices:3,price:500,text:'Restore 45% of maximum HP and cure major status.'}];
export function cossenneServices(s){const q=s.cossenneServices??={};q.version=1;q.serial=Number.isSafeInteger(q.serial)&&q.serial>=0?q.serial:0;q.wins=Number.isSafeInteger(q.wins)&&q.wins>=0?q.wins:0;q.relief??={accepted:false,posts:[],claimed:false};q.relief.posts=[...new Set((q.relief.posts||[]).filter(k=>RELIEF_POSTS.some(p=>p.key===k)))];return q;}
export function startConservatoryBoard(s){const q=cossenneServices(s);if(q.game&&!q.game.complete)return false;let seed=(++q.serial*2654435761)>>>0;const cards=[...CONSERVATORY_TYPES,...CONSERVATORY_TYPES];for(let i=cards.length-1;i>0;i--){seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;const j=(seed>>>0)%(i+1);[cards[i],cards[j]]=[cards[j],cards[i]];}q.game={cards,matched:[],flipped:[],turns:0,complete:false,prize:0};return true;}
export function flipConservatoryCard(s,index){const q=cossenneServices(s),g=q.game;if(!g||g.complete||!Number.isInteger(index)||index<0||index>=g.cards.length||g.flipped.length>=2||g.flipped.includes(index)||g.matched.includes(index))return false;g.flipped.push(index);if(g.flipped.length===2){g.turns++;const [a,b]=g.flipped;if(g.cards[a]===g.cards[b]){g.matched.push(a,b);g.flipped=[];if(g.matched.length===g.cards.length){g.complete=true;g.prize=400+(g.turns<=9?200:0);s.money=(s.money||0)+g.prize;q.wins++;q.best=q.best?Math.min(q.best,g.turns):g.turns;if(!q.firstPrize){q.firstPrize=true;s.resinLoaves=(s.resinLoaves||0)+4;s.trainingTonics=(s.trainingTonics||0)+1;}}}}return true;}
export function coverConservatoryCards(s){const g=cossenneServices(s).game;if(!g||g.complete||g.flipped.length!==2)return false;g.flipped=[];return true;}
export function craftApothecary(s,id){const r=APOTHECARY_RECIPES.find(r=>r.id===id);if(!r||!(s.poultices>=r.poultices)||!(s.money>=r.price))return false;s.poultices-=r.poultices;s.money-=r.price;s[r.key]=(s[r.key]||0)+1;return true;}
export function acceptRelief(s){const q=cossenneServices(s).relief;if(q.accepted||q.claimed)return false;q.accepted=true;return true;}
export function prepareReliefPost(s,key,room){const q=cossenneServices(s).relief,p=RELIEF_POSTS.find(p=>p.key===key);if(!q.accepted||q.claimed||!p||p.room!==room||q.posts.includes(key))return false;q.posts.push(key);return true;}
export function claimRelief(s){const q=cossenneServices(s).relief;if(!q.accepted||q.claimed||q.posts.length!==RELIEF_POSTS.length)return false;q.claimed=true;s.money=(s.money||0)+2500;s.armedEscorts=(s.armedEscorts||0)+2;s.cleansingBalms=(s.cleansingBalms||0)+2;return true;}
export function reliefJournal(s){const q=cossenneServices(s).relief;if(q.claimed)return 'Firewatch relief: complete. Cossenne specialist foods and medicines now cost 10% less.';if(!q.accepted)return 'Firewatch relief: visit the Firewatch Cistern in southeast Cossenne to help the road’s civilian supply posts.';const remaining=RELIEF_POSTS.filter(p=>!q.posts.includes(p.key));return remaining.length?'Firewatch relief: prepare '+remaining.map(p=>p.name+' on '+p.route).join(', ')+'. Follow each marked relief crate and press A. Then return to the Firewatch Cistern.':'Firewatch relief: all three posts ready. Return to the Cossenne Firewatch Cistern for 2,500 doubloons, two Armed Escorts, two Cleansing Balms and the permanent specialist discount.';}

export function cossenneServiceObjective(s,room){const data={cossenneConservatory:['cs-conservatory-work','Use the nursery board for a paid matching game, or browse specialist capture foods'],cossenneApothecary:['cs-apothecary-work','Use the medicine bench to craft stronger treatments from spare Poultices'],cossenneFirewatch:['cs-firewatch-work','Read the relief dispatch board and prepare the three roadside supply posts']};return data[room]?{spot:data[room][0],text:data[room][1]}:null;}
